    {t: 'Liver monitoring targets populations with many fast acetylators: <b>Japanese and Caucasian</b> patients. For a <b>Middle Eastern</b> patient, most likely slow, nerve damage is the first thing to watch for.',
     svg: '<svg viewBox="0 0 360 290" role="img" aria-label="Tags beside the bars: monitor liver for Japanese and Caucasian, nerve damage for Middle Eastern."><rect x="8" y="10" width="22" height="14" rx="2" class="s3box"/><text x="38" y="22" class="s3txt" text-anchor="start">slow acetylator</text><text x="38" y="38" class="s3sub" text-anchor="start">isoniazid stays: peripheral nerve damage</text><rect x="8" y="50" width="22" height="14" rx="2" class="s3hi"/><text x="38" y="62" class="s3txt" text-anchor="start">fast acetylator</text><text x="38" y="78" class="s3sub" text-anchor="start">metabolites: hepatotoxicity</text><text x="8" y="133" class="s3txt" text-anchor="start">Japanese</text><text x="112" y="112" class="s3sub" text-anchor="start">about 10% slow, the rest probably fast</text><rect x="112" y="118" width="15" height="22" rx="0" class="s3box"/><rect x="127" y="118" width="135" height="22" rx="0" class="s3hi"/><text x="270" y="133" class="s3txt" text-anchor="start">monitor liver</text><text x="8" y="193" class="s3txt" text-anchor="start">Caucasian</text><text x="112" y="172" class="s3sub" text-anchor="start">30-45% fast (about half)</text><rect x="112" y="178" width="45" height="22" rx="0" class="s3hi"/><rect x="157" y="178" width="22.5" height="22" rx="0" class="s3hi" stroke-dasharray="3 3" fill-opacity="0.4"/><rect x="179.5" y="178" width="82.5" height="22" rx="0" class="s3box"/><text x="270" y="193" class="s3txt" text-anchor="start">monitor liver</text><text x="8" y="253" class="s3txt" text-anchor="start">Middle Eastern</text><text x="112" y="232" class="s3sub" text-anchor="start">about 80% slow</text><rect x="112" y="238" width="120" height="22" rx="0" class="s3box"/><rect x="232" y="238" width="30" height="22" rx="0" class="s3hi"/><text x="270" y="253" class="s3txt" text-anchor="start">nerve damage</text></svg>'}
