  {t: 'Vitamin K works against warfarin (it is warfarin\'s antidote), so <b>more warfarin</b> is needed to anticoagulate the patient.',
   svg: '<svg viewBox="0 0 360 300" role="img" aria-label="Vitamin K level bar; CYP4F2 removes vitamin K to hydroxyvitamin K1; a CYP4F2 activity bar and a warfarin dose bar."><defs><marker id="mL-v4-L21-cyp4f2-2" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="8" markerHeight="8" markerUnits="userSpaceOnUse" orient="auto"><path d="M1,1 L8,5 L1,9" class="s3line"/></marker><marker id="mA-v4-L21-cyp4f2-2" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="8" markerHeight="8" markerUnits="userSpaceOnUse" orient="auto"><path d="M1,1 L8,5 L1,9" class="s3acc"/></marker></defs><text x="70" y="18" class="s3txt" text-anchor="middle">Vitamin K</text><text x="70" y="34" class="s3sub" text-anchor="middle">in the cycle</text><rect x="50" y="44" width="40" height="120" rx="3" class="s3box"/><rect x="50" y="74" width="40" height="90" rx="3" class="s3box" fill-opacity="0.9"/><path d="M96,104 L176,104" class="s3line" marker-end="url(#mL-v4-L21-cyp4f2-2)"/><text x="136" y="96" class="s3sub" text-anchor="middle">CYP4F2</text><rect x="180" y="84" width="100" height="40" rx="6" class="s3box"/><text x="230" y="102" class="s3sub" text-anchor="middle">hydroxy-</text><text x="230" y="116" class="s3sub" text-anchor="middle">vitamin K1</text><text x="230" y="140" class="s3sub" text-anchor="middle">removed</text><text x="156" y="158" class="s3sub" text-anchor="middle">CYP4F2 activity</text><rect x="116" y="166" width="80" height="14" rx="3" class="s3box"/><rect x="116" y="166" width="32" height="14" rx="3" class="s3box"/><text x="156" y="198" class="s3sub" text-anchor="middle">CYP4F2*3: less active</text><path d="M96,240 L240,240" class="s3acc" marker-end="url(#mA-v4-L21-cyp4f2-2)"/><text x="168" y="230" class="s3sub" text-anchor="middle">works against warfarin</text><rect x="10" y="222" width="84" height="36" rx="6" class="s3box"/><text x="52" y="245" class="s3txt" text-anchor="middle">Vitamin K</text><text x="310" y="18" class="s3sub" text-anchor="middle">warfarin dose</text><rect x="290" y="30" width="40" height="200" rx="3" class="s3box"/><rect x="290" y="90" width="40" height="140" rx="3" class="s3hi" fill-opacity="1"/></svg>'},
  {t: 'On the non-African branch CYP4F2*3 adds about <b>5 to 10%</b> to the calculated dose, graded optional. With VKORC1, CYP2C9 and CYP4F2 reported, the branch inputs are complete.',
   svg: '<svg viewBox="0 0 360 300" role="img" aria-label="Vitamin K level bar; CYP4F2 removes vitamin K to hydroxyvitamin K1; a CYP4F2 activity bar and a warfarin dose bar."><defs><marker id="mL-v4-L21-cyp4f2-3" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="8" markerHeight="8" markerUnits="userSpaceOnUse" orient="auto"><path d="M1,1 L8,5 L1,9" class="s3line"/></marker><marker id="mA-v4-L21-cyp4f2-3" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="8" markerHeight="8" markerUnits="userSpaceOnUse" orient="auto"><path d="M1,1 L8,5 L1,9" class="s3acc"/></marker></defs><text x="70" y="18" class="s3txt" text-anchor="middle">Vitamin K</text><text x="70" y="34" class="s3sub" text-anchor="middle">in the cycle</text><rect x="50" y="44" width="40" height="120" rx="3" class="s3box"/><rect x="50" y="74" width="40" height="90" rx="3" class="s3box" fill-opacity="0.9"/><path d="M96,104 L176,104" class="s3line" marker-end="url(#mL-v4-L21-cyp4f2-3)"/><text x="136" y="96" class="s3sub" text-anchor="middle">CYP4F2</text><rect x="180" y="84" width="100" height="40" rx="6" class="s3box"/><text x="230" y="102" class="s3sub" text-anchor="middle">hydroxy-</text><text x="230" y="116" class="s3sub" text-anchor="middle">vitamin K1</text><text x="230" y="140" class="s3sub" text-anchor="middle">removed</text><text x="156" y="158" class="s3sub" text-anchor="middle">CYP4F2 activity</text><rect x="116" y="166" width="80" height="14" rx="3" class="s3box"/><rect x="116" y="166" width="32" height="14" rx="3" class="s3box"/><text x="156" y="198" class="s3sub" text-anchor="middle">CYP4F2*3: less active</text><path d="M96,240 L240,240" class="s3line" marker-end="url(#mL-v4-L21-cyp4f2-3)"/><text x="168" y="230" class="s3sub" text-anchor="middle">works against warfarin</text><rect x="10" y="222" width="84" height="36" rx="6" class="s3box"/><text x="52" y="245" class="s3txt" text-anchor="middle">Vitamin K</text><text x="310" y="18" class="s3sub" text-anchor="middle">warfarin dose</text><rect x="290" y="30" width="40" height="200" rx="3" class="s3box"/><rect x="290" y="90" width="40" height="140" rx="3" class="s3hi" fill-opacity="1"/><path d="M310,140 L310,96" class="s3acc" marker-end="url(#mA-v4-L21-cyp4f2-3)"/><text x="310" y="252" class="s3sub" text-anchor="middle">+ 5 to 10%</text><text x="310" y="268" class="s3sub" text-anchor="middle">optional</text><text x="150" y="290" class="s3sub" text-anchor="middle">non-African branch only</text></svg>'}
